	o := &LLMProviderProbeResult{}
	if err = randomize.Struct(seed, o, llmProviderProbeResultDBTypes, true, llmProviderProbeResultColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize LLMProviderProbeResult struct: %s", err)
	}

	ctx := context.Background()
